// Turn n8n's error object into a dead letter someone can act on.
//
// The reason code comes from the CLOSED SET in docs/contracts.md. Two of them exist for
// exactly this path:
//
//   service_unreachable  the review service is not answering. In a two-process local setup
//                        this is the likeliest failure there is (assumptions.md), and it is
//                        the one E7-S3's drill forces.
//   workflow_error       anything else n8n threw. Deliberately vague, and it earns that by
//                        carrying the workflow, the node and the message beside it.
//
// Everything else in the set names something a COMPONENT decided. A workflow that threw
// decided nothing, so borrowing one of those codes would put a run that died into the same
// bucket as a run that stopped on purpose.

const e = $json.execution ?? {};
const w = $json.workflow ?? {};
const err = e.error ?? {};
const message = String(err.message ?? err.description ?? 'no message');
const cause = String(err.cause?.code ?? err.code ?? '');

// WHERE THE IDS COME FROM, and this took three drill runs to get right.
//
// The obvious place is the failing node's input, and n8n 2.x does not provide it: the error
// trigger receives {execution:{id,url,error,lastNodeExecuted,mode}, workflow:{id,name}} and
// **no `execution.data`**, so there is no runData to walk. A dead letter built from the
// item that failed is a dead letter with nothing in it.
//
// What IS there is the request that failed, inside the error. Every service call on this
// spine names the document either in its path (`/api/documents/DOC-…`) or in its JSON body,
// so the identity of the run is recoverable from the attempt itself.
// n8n's error shape is its own and undocumented, and it moved between the version this was
// written against and the one that runs it. So this SEARCHES the serialised error rather
// than walking a path into it: two expressions, extracting two ids and nothing else. Header
// values are already redacted by n8n before the error reaches here.
//
// Where they come from: every service call on this spine names the document either in its
// path (`/api/documents/DOC-…`) or in its JSON body, so the identity of the run survives in
// the attempt that failed even when nothing else does.
const blob = JSON.stringify(err);
const find = (re) => (blob.match(re) || [])[1] ?? null;

const doc_id = find(/"doc_id"\s*:\s*"([^"]+)"/)
  ?? find(/\/api\/documents\/([^/?#"\\]+)/);
const trace_id = find(/"trace_id"\s*:\s*"([^"]+)"/);

// A connection that never reached the far end, versus a service that answered badly. Only
// the first is service_unreachable — the second is a component's own refusal, and it has a
// reason code of its own already.
//
// n8n rewrites transport errors into friendly prose ("The service refused the connection -
// perhaps it is offline"), so matching on the errno alone missed the very failure this code
// was written for. Both wordings, and the errno where n8n keeps it.
const UNREACHABLE = /ECONNREFUSED|ECONNRESET|ENOTFOUND|EHOSTUNREACH|EAI_AGAIN|ETIMEDOUT|socket hang up|fetch failed|refused the connection|could not be reached|is offline/i;

// The provider call is exempt from ever reaching here (it is continueRegularOutput, and
// "Parse or park" classifies it), so a connection failure that DOES reach WF4 came from a
// call to the review service. That is what lets this be decided on the message alone.
const unreachable = UNREACHABLE.test(`${message} ${cause}`);

return [{
  json: {
    reason: unreachable ? 'service_unreachable' : 'workflow_error',
    component: 'error_handler',
    // Either may be null and the row is still stored. The service fills in a missing
    // trace_id from the document when it can, because that is its own data to look up.
    trace_id,
    doc_id,
    workflow: w.name ?? w.id ?? null,
    node: e.lastNodeExecuted ?? null,
    message: message.slice(0, 500),
    execution_id: e.id ?? (String(e.url ?? '').match(/executions\/(\d+)/) || [])[1] ?? null,
    execution_url: e.url ?? null,
  },
}];
